package com.morgana.domain.script

import com.morgana.domain.spatial.Direction
import com.morgana.domain.stats.ActiveStatusEffect
import com.morgana.domain.stats.StatusEffectType
import kotlinx.serialization.Serializable

/**
 * Declarative side-effects generated by scripts.
 *
 * Scripts never mutate simulation memory directly. Instead, they produce a list of [ScriptEffect]
 * values which the simulation validates and applies via [com.morgana.domain.replay.SimInput.ExecuteScriptEffect],
 * preserving full determinism and replayability.
 */
@Serializable
sealed interface ScriptEffect {
    @Serializable
    data class DamagePlayer(
        val targetId: String,
        val amount: Int,
        val vitalId: String = "hp",
        val sourceId: String? = null
    ) : ScriptEffect

    @Serializable
    data class DamageNpc(
        val mapId: Int,
        val npcInstanceId: String,
        val amount: Int,
        val vitalId: String = "hp",
        val sourcePlayerId: String? = null
    ) : ScriptEffect

    @Serializable
    data class HealPlayer(
        val targetId: String,
        val amount: Int,
        val vitalId: String = "hp"
    ) : ScriptEffect

    @Serializable
    data class HealNpc(
        val mapId: Int,
        val npcInstanceId: String,
        val amount: Int,
        val vitalId: String = "hp"
    ) : ScriptEffect

    @Serializable
    data class GiveItem(
        val playerId: String,
        val itemId: Int,
        val amount: Int = 1
    ) : ScriptEffect

    @Serializable
    data class RemoveItem(
        val playerId: String,
        val itemId: Int,
        val amount: Int = 1
    ) : ScriptEffect

    @Serializable
    data class WarpPlayer(
        val playerId: String,
        val mapId: Int,
        val x: Int,
        val y: Int
    ) : ScriptEffect

    @Serializable
    data class ApplyStatus(
        val targetPlayerId: String,
        val effect: ActiveStatusEffect
    ) : ScriptEffect

    @Serializable
    data class RemoveStatus(
        val targetPlayerId: String,
        val type: StatusEffectType
    ) : ScriptEffect

    @Serializable
    data class BroadcastMessage(
        val message: String,
        val mapId: Int? = null,
        val colorHex: String = "#E2E8F0"
    ) : ScriptEffect

    @Serializable
    data class SendPlayerMessage(
        val playerId: String,
        val message: String,
        val colorHex: String = "#E2E8F0"
    ) : ScriptEffect

    @Serializable
    data class EmitFloatingText(
        val mapId: Int,
        val x: Int,
        val y: Int,
        val text: String,
        val category: String = "script",
        val colorHex: String = "#FACC15"
    ) : ScriptEffect

    @Serializable
    data class TriggerAnimation(
        val mapId: Int,
        val x: Int,
        val y: Int,
        val animationId: Int,
        val soundId: String = ""
    ) : ScriptEffect

    @Serializable
    data class SpawnProjectile(
        val mapId: Int,
        val sourceEntityId: String,
        val isFromPlayer: Boolean,
        val currentTileX: Int,
        val currentTileY: Int,
        val direction: Direction,
        val remainingTiles: Int,
        val spriteId: Int = 1,
        val damage: Int = 1,
        val ticksPerTile: Int = 1,
        val spellId: Int = 0
    ) : ScriptEffect

    @Serializable
    data class AwardExperience(
        val playerId: String,
        val amount: Long
    ) : ScriptEffect

    @Serializable
    data class ConsumeVital(
        val playerId: String,
        val vitalId: String,
        val amount: Int
    ) : ScriptEffect

    /**
     * Books a one-off schedule (see `WorldSimulation.scheduleOnce`): it raises warnings and a start at [atMillis] (epoch
     * milliseconds, from `world.now_ms`), announced in chat and passed to `register.schedule` hooks with [data]. Ignored if the
     * scheduler is off, the time is not in the future, or [id] is a `game.json` schedule's.
     */
    @Serializable
    data class ScheduleOnce(
        val id: String,
        val atMillis: Long,
        val name: String = "",
        val warningsSeconds: List<Int> = emptyList(),
        val data: Map<String, String> = emptyMap(),
        val warningMessage: String = com.morgana.domain.game.ScheduleDefinition.DEFAULT_WARNING_MESSAGE,
        val fireMessage: String = com.morgana.domain.game.ScheduleDefinition.DEFAULT_FIRE_MESSAGE
    ) : ScriptEffect

    /** Places a world object of [kind] on a tile (see `WorldSimulation.placeWorldObject`); ignored if the placement is refused. */
    @Serializable
    data class PlaceObject(
        val kind: String, val mapId: Int, val x: Int, val y: Int,
        val ownerId: String? = null, val data: Map<String, String> = emptyMap()
    ) : ScriptEffect

    /** Takes a world object away, with [reason] for observers. */
    @Serializable
    data class RemoveObject(val id: String, val reason: String = "removed") : ScriptEffect

    /** Hurts a world object; it is destroyed when its hit points run out. */
    @Serializable
    data class DamageObject(val id: String, val amount: Int) : ScriptEffect

    /** Replaces what is kept on a world object. */
    @Serializable
    data class SetObjectData(val id: String, val data: Map<String, String>) : ScriptEffect

    /** Cancels a one-off booked with [ScheduleOnce]. */
    @Serializable
    data class CancelSchedule(val id: String) : ScriptEffect

    /**
     * Replaces the script state stored under [key] with [values]; an empty map deletes the key. Script state is how a
     * stateless Lua hook remembers things between ticks (an action-combat skill in progress, a buffered input). It is
     * kept in the simulation, hashed for replays and not saved. Values are strings: scripts convert with `tonumber`.
     */
    @Serializable
    data class SetState(
        val key: String,
        val values: Map<String, String> = emptyMap()
    ) : ScriptEffect
}
